要计算两个矩阵A和B的乘积，可以按照以下步骤：
1.定义两个矩阵A和B，以及一个结果矩阵C。矩阵A和B的大小分别为n*m和m*p，结果矩阵C的大小为n*p。
2.从矩阵A中取出一行，从矩阵B中取出一列，将它们依次相乘并累加，得到结果矩阵C的一个元素。
3.重复步骤2，直至得到结果矩阵C的全部元素。
以下是用C++代码实现矩阵乘积的示例：
```cpp
#include <iostream>
using namespace std;
const int MAX_SIZE = 10;
int main()
{
    int n, m, p;
    int A[MAX_SIZE][MAX_SIZE], B[MAX_SIZE][MAX_SIZE], C[MAX_SIZE][MAX_SIZE];

    // 输入矩阵A和B的大小
    cout << "Enter the size of matrix A(n*m): ";
    cin >> n >> m;
    cout << "Enter the size of matrix B(m*p): ";
    cin >> m >> p;

    // 输入矩阵A
    cout << "Enter the elements of matrix A:\n";
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> A[i][j];
        }
    }

    // 输入矩阵B
    cout << "Enter the elements of matrix B:\n";
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            cin >> B[i][j];
        }
    }

    // 计算矩阵C
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < p; j++) {
            C[i][j] = 0;
            for (int k = 0; k < m; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    // 输出矩阵C
    cout << "The product of matrix A and B is:\n";
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < p; j++) {
            cout << C[i][j] << " ";
        }
        cout << endl;
    }

    return 0;
}
```

